package com.lbos.commercecustomer.service;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.exception.*;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.impl.*;import java.time.LocalDate;import java.util.*;import org.junit.jupiter.api.Test;class CustomerServiceImplTest{@Test void createsProfile(){var repository=mock(CustomerProfileRepository.class);when(repository.save(any())).thenAnswer(invocation->{CustomerProfile savedProfile=invocation.getArgument(0);savedProfile.setId(UUID.randomUUID());return savedProfile;});var service=new CustomerServiceImpl(repository,new CommerceMapper(),mock(ContextSupport.class));assertNotNull(service.create(new CreateCustomerRequest(UUID.randomUUID(),LocalDate.of(2000,1,1))).id());}@Test void duplicateRejected(){var repository=mock(CustomerProfileRepository.class);when(repository.existsByUserAccountId(any())).thenReturn(true);var service=new CustomerServiceImpl(repository,new CommerceMapper(),mock(ContextSupport.class));assertThrows(DuplicateResourceException.class,()->service.create(new CreateCustomerRequest(UUID.randomUUID(),LocalDate.of(2000,1,1))));}@Test void boundaryNullDobAllowed(){var repository=mock(CustomerProfileRepository.class);when(repository.save(any())).thenAnswer(invocation->invocation.getArgument(0));var service=new CustomerServiceImpl(repository,new CommerceMapper(),mock(ContextSupport.class));assertNull(service.create(new CreateCustomerRequest(UUID.randomUUID(),null)).dateOfBirth());}}
